pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(recipient != address(0));
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;

        // Record expected behavior: only owner (address(this)) can withdraw
        bool isOwner = (caller == address(this));

        // Attempt withdrawal
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, recipient));

        // Rule: If call succeeded (no revert), the balance must have decreased by at least the amount transferred
        // Since owner always succeeds and non-owner fails, we check consistency
        // For non-owner: call should revert, so success is false and balance unchanged
        // For owner: call should succeed, balance decreases by 1 ether (or to 0)
        if (isOwner) {
            assertTrue(success);
            assertTrue(address(c).balance < balanceBefore || address(c).balance == 0);
        } else {
            assertTrue(!success);
            assertEq(address(c).balance, balanceBefore);
        }
    }
}

